import fs from 'node:fs';
import path from 'node:path';
import solc from 'solc';

// One canonical compiler input is used to generate both deployment bytecode and
// the exact Etherscan V2 verification payload. Never hand-edit generated files.
const root=process.cwd();
const contractPath='contracts/IndexioPayRouter_V1.sol';
const source=fs.readFileSync(path.join(root,contractPath),'utf8');
const input={
 language:'Solidity',
 sources:{[contractPath]:{content:source}},
 settings:{
  optimizer:{enabled:true,runs:200},
  evmVersion:'cancun',
  outputSelection:{'*':{'*':['abi','evm.bytecode.object','evm.deployedBytecode.object','metadata']}}
 }
};
const output=JSON.parse(solc.compile(JSON.stringify(input)));
for(const issue of output.errors||[]) (issue.severity==='error'?console.error:console.warn)(issue.formattedMessage||issue.message);
if((output.errors||[]).some(issue=>issue.severity==='error'))process.exit(1);
const artifact=output.contracts?.[contractPath]?.IndexioPayRouter;
if(!artifact?.evm?.bytecode?.object||!artifact?.abi)throw Error('IndexioPayRouter compilation did not return deployable bytecode');
const deployedBytes=artifact.evm.deployedBytecode.object.length/2;
if(deployedBytes>24576)throw Error('Pay Router exceeds Base contract code size limit');
const compiler='v'+(solc.version().match(/^\d+\.\d+\.\d+\+commit\.[0-9a-f]+/)?.[0]||'');
if(compiler==='v')throw Error('Could not derive the exact Solidity compiler version for Etherscan');
const header='// AUTOGENERATED by scripts/compile-indexio-pay.mjs — do not edit.\n';
fs.writeFileSync(path.join(root,'lib/indexio-pay.generated.ts'),header+
 `export const indexioPayAbi=${JSON.stringify(artifact.abi)} as const;\n`+
 `export const indexioPayBytecode=${JSON.stringify('0x'+artifact.evm.bytecode.object)} as \`0x\${string}\`;\n`+
 `export const indexioPayCompiler=${JSON.stringify(compiler)} as const;\n`);
fs.writeFileSync(path.join(root,'lib/indexio-pay-verification.generated.ts'),header+
 `export const indexioPayStandardJsonInput=${JSON.stringify(JSON.stringify(input))} as const;\n`+
 `export const indexioPayCompiler=${JSON.stringify(compiler)} as const;\n`+
 `export const indexioPayCreationBytecode=${JSON.stringify('0x'+artifact.evm.bytecode.object)} as \`0x\${string}\`;\n`);
fs.mkdirSync(path.join(root,'artifacts'),{recursive:true});
fs.writeFileSync(path.join(root,'artifacts/indexio-pay-standard-json-input.json'),JSON.stringify(input,null,2));
fs.writeFileSync(path.join(root,'artifacts/indexio-pay-contract.json'),JSON.stringify({contract:contractPath+':IndexioPayRouter',compiler,optimizerRuns:200,evmVersion:'cancun',abi:artifact.abi,bytecode:'0x'+artifact.evm.bytecode.object},null,2));
console.log(`Indexio Pay Router compiled with ${compiler} (${deployedBytes} runtime bytes).`);
